import unittest
from xml.dom.minidom import Document, Element

from SCFC_reader import ScfcReader


class TestScfcReader(unittest.TestCase):
    def setUp(self):
        self.scfc_reader = ScfcReader()

    def test_open_file(self):
        xml_document = self.scfc_reader.open_file("/home/ute/Desktop/Add_cell_2.xml")
        self.assertTrue(isinstance(xml_document, Document))

    def test_get_xml_managed_objects(self):
        xml_document = self.xml_document = self.scfc_reader.open_file("/home/ute/Desktop/Add_cell_2.xml")
        managed_objects = self.scfc_reader.get_xml_managed_objects(xml_document)
        self.assertEqual(len(managed_objects), 6)
        self.assertTrue(all(isinstance(mo, Element) for mo in managed_objects))


if __name__ == "__main__":
    unittest.main()
